import struct,zlib,collections
b=open('sheet.png','rb').read(); p=8; ids=[]
while p<len(b):
 n=struct.unpack('>I',b[p:p+4])[0]; typ=b[p+4:p+8]; d=b[p+8:p+8+n]; p+=n+12
 if typ==b'IHDR': print('IHDR',struct.unpack('>IIBBBBB',d))
